// Each link's state as GitHub has it, read with one `gh api graphql` call for
// every link at once, so a pull request merged or an issue closed anywhere,
// by anyone, shows in the Links section. register.tsx runs the read; nothing
// here calls `$`.

import type { LinkState, SessionLink, SessionStatus } from '../types'

/** How often the links' states are read again while the session works. */
export const LINK_STATE_REFRESH_MS = 2 * 60_000

/** How long one read may take. */
export const LINK_STATE_TIMEOUT_MS = 15_000

/** A command that may change a page's state: a read follows it at once. */
const GH_PAGE_COMMAND = /(?:^|[\s;&|(])gh\s+(?:pr|issue)\s/

/** The `gh` call that reads every link's state; null when there is no link. */
export function linkStatesArgv(links: readonly SessionLink[]): string[] | null {
  const repos = [...new Set(links.map(link => link.repo))]
  if (repos.length === 0) {
    return null
  }
  const fields = repos.map((repo, index) => {
    const [owner = '', name = ''] = repo.split('/')
    const pages = [...new Set(links.filter(link => link.repo === repo).map(link => link.number))]
      .map(number => `n${number}: issueOrPullRequest(number: ${number}) { ... on PullRequest { state } ... on Issue { state } }`)
      .join(' ')

    return `r${index}: repository(owner: ${JSON.stringify(owner)}, name: ${JSON.stringify(name)}) { ${pages} }`
  })

  return ['gh', 'api', 'graphql', '-f', `query=query { ${fields.join(' ')} }`]
}

/**
 * The states a read found, by page URL. A repository or page GitHub did not
 * answer for (gone, private, a typo) is left out, so its link keeps the state
 * it had; output that is no answer at all finds none.
 */
export function parseLinkStates(stdout: string, links: readonly SessionLink[]): Map<string, LinkState> {
  const states = new Map<string, LinkState>()
  let data: Record<string, Record<string, { state?: unknown } | null> | null>
  try {
    data = (JSON.parse(stdout) as { data?: typeof data }).data ?? {}
  } catch {
    return states
  }
  const repos = [...new Set(links.map(link => link.repo))]
  for (const link of links) {
    const state = data?.[`r${repos.indexOf(link.repo)}`]?.[`n${link.number}`]?.state
    const read = state === 'MERGED' ? 'merged' : state === 'CLOSED' ? 'closed' : state === 'OPEN' ? 'open' : null
    if (read !== null) {
      states.set(link.url, read)
    }
  }

  return states
}

/** The status with each link's state set to what GitHub said; the same status when nothing changed. */
export function withLinkStates(status: SessionStatus, states: ReadonlyMap<string, LinkState>): SessionStatus {
  let isChanged = false
  const links = status.links.map(link => {
    const state = states.get(link.url)
    if (state === undefined || state === (link.state ?? 'open')) {
      return link
    }
    isChanged = true

    return { ...link, state }
  })

  return isChanged ? { ...status, links } : status
}

/**
 * Whether a read of the links' states is due after a tool call: never
 * without a link; at once after a link joins or a `gh pr` or `gh issue`
 * command; else once LINK_STATE_REFRESH_MS passed since the last read.
 */
export function isLinkStateReadDue(
  status: SessionStatus | null,
  lastRead: { links: number; at: number } | null,
  call: { tool: string; command?: unknown },
  now: number,
): boolean {
  const links = status?.links.length ?? 0
  if (links === 0) {
    return false
  }
  const isGhPageCommand = call.tool === 'Bash' && typeof call.command === 'string' && GH_PAGE_COMMAND.test(call.command)

  return lastRead === null || lastRead.links !== links || isGhPageCommand || now - lastRead.at >= LINK_STATE_REFRESH_MS
}

files.hooks/links.ts:
// The pull requests and issues a session creates, found in what `gh pr
// create` and `gh issue create` print: the new page's URL. The status tool's
// `link` action adds a page the session did not create, by its URL. The
// Links section shows them all alike. The `gh` commands that merge, close or
// reopen a page change its state.

import type { LinkState, SessionLink, SessionStatus } from '../types'
import { simpleCommands } from './shell'

/** The `gh` commands that create a page, and the URL path each one prints. */
const CREATES = [
  { kind: 'pr', command: /^gh\s+pr\s+create\b/, path: 'pull' },
  { kind: 'issue', command: /^gh\s+issue\s+create\b/, path: 'issues' },
] as const

const PAGE_URL = /https:\/\/[^\s/]+\/([\w.-]+)\/([\w.-]+)\/(pull|issues)\/(\d+)(?![\w/])/g

/** The `gh` commands that change a page's state, and the state each one leaves. */
const STATE_COMMANDS = [
  { kind: 'pr', command: /^gh\s+pr\s+merge\b/, state: 'merged' },
  { kind: 'pr', command: /^gh\s+pr\s+close\b/, state: 'closed' },
  { kind: 'pr', command: /^gh\s+pr\s+reopen\b/, state: 'open' },
  { kind: 'issue', command: /^gh\s+issue\s+close\b/, state: 'closed' },
  { kind: 'issue', command: /^gh\s+issue\s+reopen\b/, state: 'open' },
] as const

/** What `gh` prints after a merge, close or reopen: `<owner>/<repo>#<n>`. */
const PRINTED_PAGE = /\b([\w.-]+\/[\w.-]+)#(\d+)\b/

/** One page's URL and nothing else, for the `link` action. */
const ONE_PAGE_URL = /^https:\/\/[^\s/]+\/([\w.-]+)\/([\w.-]+)\/(pull|issues)\/(\d+)\/?$/

/** A page as the pane names it: `<repo>#<number>`. */
export type FoundLink = Pick<SessionLink, 'kind' | 'repo' | 'number' | 'url'>

/**
 * The pages a shell command created: each URL of its kind in the output of a
 * command that runs `gh pr create` or `gh issue create` as one of its simple
 * commands. Nothing for any other command, or for the text of a heredoc or
 * an argument, so a URL a command only printed is never taken.
 */
export function findCreatedLinks(command: string, output: string): FoundLink[] {
  const parts = simpleCommands(command)
  const found: FoundLink[] = []
  for (const create of CREATES) {
    if (!parts.some(part => create.command.test(part))) {
      continue
    }
    for (const match of output.matchAll(PAGE_URL)) {
      const [url, owner, repo, path, number] = match as unknown as [string, string, string, string, string]
      if (path === create.path) {
        found.push({ kind: create.kind, repo: `${owner}/${repo}`, number: Number(number), url })
      }
    }
  }

  return found
}

/** The page a `link` call names: a pull request's or issue's URL; null for any other text. */
export function readPageUrl(url: string): FoundLink | null {
  const page = url.trim().replace(/\/$/, '')
  const match = ONE_PAGE_URL.exec(page)
  if (match === null) {
    return null
  }
  const [, owner, repo, path, number] = match as unknown as [string, string, string, string, string]

  return { kind: path === 'pull' ? 'pr' : 'issue', repo: `${owner}/${repo}`, number: Number(number), url: page }
}

/** The `<repo>#<number>` a link shows: the repository's name without its owner. */
export function linkLabel(link: Pick<SessionLink, 'repo' | 'number'>): string {
  return `${link.repo.split('/').pop() ?? link.repo}#${link.number}`
}

/** A page a command merged, closed or reopened; `repo` null when the command named only its number. */
export type StateChange = { kind: SessionLink['kind']; repo: string | null; number: number; state: LinkState }

/**
 * The state changes in a shell command: each `gh pr merge`, `close` or
 * `reopen` and `gh issue close` or `reopen` in it, with the page it names by
 * number, `#<n>` or URL (and `--repo`). A command that names no page acts on
 * the current branch's pull request: its page is read from what `gh` printed,
 * when the command holds one change alone. `gh pr merge --auto` merges later
 * and changes nothing now.
 */
export function findStateChanges(command: string, output: string): StateChange[] {
  const parts = simpleCommands(command).flatMap(part => {
    const known = STATE_COMMANDS.find(entry => entry.command.test(part))
    return known === undefined || (known.state === 'merged' && /\s--auto\b/.test(part)) ? [] : [{ part, known }]
  })
  const changes: StateChange[] = []
  for (const { part, known } of parts) {
    const page = namedPage(part) ?? (parts.length === 1 ? printedPage(output) : null)
    if (page !== null) {
      changes.push({ kind: known.kind, state: known.state, ...page })
    }
  }

  return changes
}

/** The page a `gh` command's arguments name, or null when they name none. */
function namedPage(part: string): { repo: string | null; number: number } | null {
  const words = part.split(/\s+/).slice(3)
  const repoAt = words.findIndex(word => word === '--repo' || word === '-R')
  const repoFlag = words.find(word => word.startsWith('--repo='))?.slice('--repo='.length)
  const repo = repoAt >= 0 ? (words[repoAt + 1] ?? null) : (repoFlag ?? null)
  for (const word of words) {
    const url = readPageUrl(word)
    if (url !== null) {
      return { repo: url.repo, number: url.number }
    }
    const number = /^#?(\d+)$/.exec(word)?.[1]
    if (number !== undefined) {
      return { repo, number: Number(number) }
    }
  }

  return null
}

/** The page `gh` printed after a merge, close or reopen, or null. */
function printedPage(output: string): { repo: string; number: number } | null {
  const match = PRINTED_PAGE.exec(output)

  return match === null ? null : { repo: match[1] ?? '', number: Number(match[2]) }
}

/**
 * The status with each changed page's state set. A change matches a link of
 * its kind and number, in its repository, or, when it names none, in the
 * session's own repository. A page that is not linked stays out.
 */
export function linkStatesChanged(status: SessionStatus, changes: readonly StateChange[]): SessionStatus {
  let isChanged = false
  let links = status.links
  for (const change of changes) {
    const repo = change.repo ?? status.place?.repo?.slug ?? null
    links = links.map(link => {
      const isPage = link.kind === change.kind && link.number === change.number && (repo === null || link.repo === repo)
      if (!isPage || (link.state ?? 'open') === change.state) {
        return link
      }
      isChanged = true

      return { ...link, state: change.state }
    })
  }

  return isChanged ? { ...status, links } : status
}

/** What the model reads after `link`: whether the page joined the links. */
export function linkedText(link: FoundLink, isAdded: boolean): string {
  const name = `${link.kind === 'pr' ? 'Pull request' : 'Issue'} ${linkLabel(link)}`

  return isAdded ? `${name} is now listed under Links.` : `${name} is listed under Links already. Nothing changed.`
}

/** The status with the found links added, each page once. */
export function linksFound(
  status: SessionStatus,
  found: readonly FoundLink[],
  stamp: { agentId?: string; at: number },
): SessionStatus {
  const added: SessionLink[] = []
  for (const link of found) {
    if ([...status.links, ...added].some(known => known.url === link.url)) {
      continue
    }
    const created: SessionLink = { ...link, at: stamp.at }
    if (stamp.agentId !== undefined) {
      created.agentId = stamp.agentId
    }
    added.push(created)
  }

  return added.length === 0 ? status : { ...status, links: [...status.links, ...added] }
}

files.hooks/reset.ts:
// Resetting the session's progress, and listing what is open, as data.
// `/session-status reset` and the status tool's `reset` action clear the
// whole record in one step, so an unrelated task starts from nothing within
// the same session (a `/clear` starts a new session, and so an empty status).
// The `list` action names every open id, which a `/compact` can leave out of
// the model's context.
// register.tsx runs both; nothing here calls `$`.

import type { SessionStatus } from '../types'
import { openItems } from './session-items'
import { isOpen } from './status'
import { ticketName } from './ticket-reports'

/** What a reset took out of the status. */
export type ResetRemoved = {
  /** Session items, dropped ones too. */
  items: number
  /** Decisions, surprises and blockers, open and closed. */
  entries: number
  /** Pull requests and issues the Links section listed. */
  links: number
  /** Reported tickets, of every effort. */
  tickets: number
  /** The effort's name; null when the session ran none. */
  effort: string | null
}

/**
 * The status without its record: the session items, the decisions,
 * surprises and blockers, the links, the reported tickets, the
 * effort and its ticket count; and what it took out. Ids start over at 1.
 * What the session runs now stays: its tasks, crons, subagents, place and
 * activity.
 */
export function resetProgress(status: SessionStatus): { status: SessionStatus; removed: ResetRemoved } {
  return {
    status: {
      ...status,
      items: [],
      links: [],
      endListPostedAt: null,
      sessionItems: [],
      ticketReports: [],
      effort: null,
      tickets: null,
    },
    removed: {
      items: status.sessionItems.length,
      entries: status.items.length,
      links: status.links.length,
      tickets: status.ticketReports.length,
      effort: status.effort?.name ?? null,
    },
  }
}

/** What the person and the model read after a reset. */
export function resetText(removed: ResetRemoved): string {
  const parts = [
    ...(removed.items > 0 ? [count(removed.items, 'session item')] : []),
    ...(removed.entries > 0 ? [count(removed.entries, 'decision, surprise or blocker', 'decisions, surprises and blockers')] : []),
    ...(removed.links > 0 ? [count(removed.links, 'link')] : []),
    ...(removed.tickets > 0 ? [count(removed.tickets, 'ticket report')] : []),
    ...(removed.effort === null ? [] : [`the effort ${removed.effort}`]),
  ]
  if (parts.length === 0) {
    return 'Session status was empty already. Nothing changed.'
  }

  return `Session status reset: removed ${joinAnd(parts)}. Everything starts over.`
}

/**
 * What the model reads after `list`: one line for each open entry, grouped
 * by kind, each with its id; a kind with no entry is left out.
 */
export function listText(status: SessionStatus): string {
  const open = status.items.filter(isOpen)
  const lines: string[] = []
  const group = (heading: string, entries: string[]) => {
    if (entries.length > 0) {
      lines.push(`${heading}:`, ...entries.map(entry => `- ${entry}`))
    }
  }
  const sessionItems = status.sessionItems.filter(item => item.state !== 'dropped')
  group(
    'Session items',
    [...openItems(status), ...sessionItems.filter(item => item.state === 'done')].map(
      item => `${item.id} ${item.title} (${item.state === 'added' ? 'open' : 'done'})`,
    ),
  )
  group(
    'Decisions',
    open.flatMap(item => (item.kind === 'decision' ? [`${item.id} ${item.question} (${item.urgency})`] : [])),
  )
  group('Blockers', open.flatMap(item => (item.kind === 'blocker' ? [`${item.id} ${item.failed}`] : [])))
  group('Surprises', open.flatMap(item => (item.kind === 'surprise' ? [`${item.id} ${item.occurred}`] : [])))
  group('Effort', status.effort === null ? [] : [status.effort.name])
  group(
    'Reported tickets',
    status.ticketReports.map(ticket => `${ticketName(ticket)} (${ticket.state})`),
  )

  return lines.length === 0 ? 'Nothing is open, and the session has no progress.' : lines.join('\n')
}

function count(n: number, noun: string, plural = `${noun}s`): string {
  return `${n} ${n === 1 ? noun : plural}`
}

function joinAnd(parts: readonly string[]): string {
  return parts.length === 1 ? (parts[0] ?? '') : `${parts.slice(0, -1).join(', ')} and ${parts.at(-1)}`
}

files.hooks/session-items.ts:
// Session items as data: the work the session is expected to do, as the main
// session reports it with the status tool's `item` action. The person's
// requests, the follow-up work the agent takes on and the steps left before
// the session settles are all items, so the total grows as the session goes
// on. register.tsx answers the `item` action with these rules;
// session-progress.ts counts the items.

import type { SessionItem, SessionStatus } from '../types'

/** What an `item` call says about one item. */
export type ItemState = SessionItem['state']

/** One `item` call, read from its input. */
export type ItemRequest =
  /** Adds a new item: it needs a title, and takes the next id. */
  | { state: 'added'; title: string }
  /** Marks an item done or dropped, by its id. */
  | { state: 'done' | 'dropped'; id: string }

/** What one `item` call did: nothing (`same`) or moved the item to its state (`moved`). */
export type ItemChange = 'same' | 'moved'

/** The items that count: all but the dropped ones. */
export function countedItems(status: SessionStatus): SessionItem[] {
  return status.sessionItems.filter(item => item.state !== 'dropped')
}

/**
 * The items the pane lists: the open ones first, oldest first, as the work
 * to do next; then the done ones, newest first. Dropped items are left out,
 * as the count leaves them out.
 */
export function listedItems(status: SessionStatus): SessionItem[] {
  const done = status.sessionItems.filter(item => item.state === 'done').reverse()

  return [...openItems(status), ...done]
}

/** The items still to do, oldest first. */
export function openItems(status: SessionStatus): SessionItem[] {
  return status.sessionItems.filter(item => item.state === 'added')
}

/**
 * The status after one `item` call, the item after it and what the call
 * did. `added` adds a new item with the next id (`I1`, `I2`, ...). `done`
 * finishes an open item; `dropped` takes an open or done item out of the
 * total, for work no longer needed or replaced by a later item. A done item
 * never goes back to added, and a dropped item stays dropped: rework is a new
 * item. Says what is wrong otherwise, for the model to fix and call again.
 */
export function reportItem(
  status: SessionStatus,
  request: ItemRequest,
  now: number,
): { status: SessionStatus; item: SessionItem; change: ItemChange } | { error: string } {
  const items = status.sessionItems
  if (request.state === 'added') {
    const highest = items
      .map(item => Number(item.id.slice(1)))
      .reduce((max, n) => (Number.isInteger(n) && n > max ? n : max), 0)
    const item: SessionItem = { id: `I${highest + 1}`, title: request.title, state: 'added', addedAt: now, at: now }

    return { status: { ...status, sessionItems: [...items, item] }, item, change: 'moved' }
  }

  const known = items.find(item => item.id === request.id.toUpperCase())
  if (known === undefined) {
    return { error: `No item ${request.id}. Use an id from an \`added\` reply (I1, I2, ...).` }
  }
  if (known.state === request.state) {
    return { status, item: known, change: 'same' }
  }
  if (known.state === 'dropped') {
    return { error: `Item ${known.id} is dropped. Add a new item for the work.` }
  }
  const item: SessionItem = { ...known, state: request.state, at: now }

  return {
    status: { ...status, sessionItems: items.map(candidate => (candidate === known ? item : candidate)) },
    item,
    change: 'moved',
  }
}

files.hooks/session-progress.ts:
// Session progress as data: the items this session is responsible for, done
// of all. The total grows as items are added. Three bars never mix (see
// docs/low-level-design.md): Session counts items, Effort the issues GitHub
// closed (effort-progress.ts), Task the task list (tasks.ts).

import type { Progress, SessionItem, SessionStatus, TicketReport } from '../types'
import { countedItems, openItems } from './session-items'
import { reportsIn } from './ticket-reports'

/** The progress the Session section shows. */
export type SessionProgress = {
  /** Items done. */
  done: number
  /** Items not dropped. */
  total: number
  /** The items still to do, oldest first. */
  open: SessionItem[]
  /** The tickets the orchestrator builds now, oldest first. */
  building: TicketReport[]
}

/**
 * A ticket whose title starts with `QA:` is checked by the person, who
 * closes it by hand: the orchestrator never lands it, so the session does
 * not count it.
 */
const QA_TITLE = /^\s*qa:/i

/** Whether a ticket title names a QA ticket. */
export function isQaTitle(title: string): boolean {
  return QA_TITLE.test(title)
}

/**
 * The session's progress: its items, done of all not dropped, and the tickets
 * the orchestrator builds now (the "Building" line); null when the session
 * has neither. Effort tickets never count here: the Effort section shows
 * which issues GitHub closed, and a session that builds a ticket adds an
 * item for it.
 */
export function sessionProgress(status: SessionStatus | null): SessionProgress | null {
  if (status === null) {
    return null
  }
  const items = countedItems(status)
  const building = reportsIn(status, 'started').filter(report => !isQaTitle(report.title))
  if (items.length === 0 && building.length === 0) {
    return null
  }

  return {
    done: items.filter(item => item.state === 'done').length,
    total: items.length,
    open: openItems(status),
    building,
  }
}

/** The task list's progress, which the Task section shows; null before the first task. */
export function taskProgress(status: SessionStatus | null): Progress | null {
  return status?.progress ?? null
}

