// Ticket reports as data: what the orchestrator says about the tickets it
// runs. Only the orchestrator knows that a ticket is being built or that its
// commit is on the effort branch; the tracker says neither until the issue
// closes, often long after. register.tsx answers the status tool's `ticket`
// action with these rules; session-progress.ts counts the reports.

import type { SessionStatus, TicketReport } from '../types'
import { withEffort } from './effort'

/** What a `ticket` call says about one ticket. `stopped` takes a started ticket back. */
export type TicketState = TicketReport['state'] | 'stopped'

/** One `ticket` call, read from its input. */
export type TicketRequest = {
  state: TicketState
  /** The ticket's issue number, when it has one. */
  number?: number
  /** The ticket's title; a ticket reported before keeps its title without one. */
  title?: string
  /** The effort's name, as its `effort:<name>` label writes it, when the call gives it. */
  effort?: string
}

/**
 * What one `ticket` call did to its ticket: nothing (`same`), moved it to the
 * state it named (`moved`), took a started ticket out (`dropped`), or took a
 * reworked one back to landed (`relanded`).
 */
export type TicketChange = 'same' | 'moved' | 'dropped' | 'relanded'

/** What one `ticket` call did: the ticket after it (null when it is not reported) and the change. */
export type TicketOutcome = { ticket: TicketReport | null; change: TicketChange }

/** The ticket's name as the tool reply writes it: `#3 Play a video`, or the title alone. */
export function ticketName(ticket: Pick<TicketReport, 'number' | 'title'>): string {
  return ticket.number === undefined ? ticket.title : `#${ticket.number} ${ticket.title}`
}

/** The ticket's short name, for lists: `#3`, or the title when it has no number. */
export function ticketShortName(ticket: Pick<TicketReport, 'number' | 'title'>): string {
  return ticket.number === undefined ? ticket.title : `#${ticket.number}`
}

/**
 * The reports of the effort the session runs now, in the order the
 * orchestrator first named them. A report made before any effort was named
 * belongs to the effort that runs now.
 */
export function effortReports(status: SessionStatus): TicketReport[] {
  const effort = status.effort?.name

  return status.ticketReports.filter(report => report.effort === undefined || report.effort === effort)
}

/** The current effort's reports of one state (see `effortReports`). */
export function reportsIn(status: SessionStatus, state: TicketReport['state']): TicketReport[] {
  return effortReports(status).filter(report => report.state === state)
}

/**
 * The status after one `ticket` call, and what the call did. A call that
 * names an effort other than the session's switches the session to it. A
 * ticket is found again by its number, or by its title when the call gives
 * no number, among the reports of the effort the call is about.
 *
 * `started` and `landed` move the ticket to that state; a landed ticket
 * started again is rework and remembers that it landed. `stopped` takes a
 * started ticket back: to landed after rework, else out of the reports. A
 * `stopped` for a ticket not started changes nothing.
 *
 * Says what is wrong when a new ticket has no title, for the model to fix
 * and call again.
 */
export function reportTicket(
  status: SessionStatus,
  request: TicketRequest,
  now: number,
): ({ status: SessionStatus } & TicketOutcome) | { error: string } {
  const switched = request.effort === undefined ? status : withEffort(status, { name: request.effort, from: 'report' })
  const reports = switched.ticketReports
  const known = effortReports(switched).find(report =>
    request.number === undefined ? report.title === request.title : report.number === request.number,
  )
  const unchanged = { status: switched, change: 'same' as const }

  if (request.state === 'stopped') {
    if (known?.state !== 'started') {
      return { ...unchanged, ticket: known ?? null }
    }
    const back: TicketReport | null =
      known.landedAt === undefined ? null : { ...withoutLandedAt(known), state: 'landed', at: known.landedAt }
    const ticketReports =
      back === null ? reports.filter(report => report !== known) : reports.map(report => (report === known ? back : report))

    return back === null
      ? { status: { ...switched, ticketReports }, ticket: known, change: 'dropped' }
      : { status: { ...switched, ticketReports }, ticket: back, change: 'relanded' }
  }

  const title = request.title ?? known?.title
  if (title === undefined) {
    return { error: "A ticket not reported before needs `title`: the ticket's title." }
  }
  if (known !== undefined && known.state === request.state && known.title === title) {
    return { ...unchanged, ticket: known }
  }
  const ticket = nextReport(known, { state: request.state, number: request.number }, title, switched.effort?.name, now)

  return {
    status: {
      ...switched,
      ticketReports:
        known === undefined ? [...reports, ticket] : reports.map(report => (report === known ? ticket : report)),
    },
    ticket,
    change: 'moved',
  }
}

/**
 * The report a `started` or `landed` call leaves. A ticket keeps the time it
 * reached its state: a second `landed` only renames it. A landed ticket
 * started again keeps when it landed, for a `stopped` to go back to.
 */
function nextReport(
  known: TicketReport | undefined,
  request: { state: TicketReport['state']; number?: number },
  title: string,
  effort: string | undefined,
  now: number,
): TicketReport {
  const number = request.number ?? known?.number
  const at = known?.state === request.state ? known.at : now
  const landedAt = request.state === 'started' && known?.state === 'landed' ? known.at : known?.landedAt
  const ticket: TicketReport = { title, state: request.state, at }
  if (number !== undefined) {
    ticket.number = number
  }
  const owner = known?.effort ?? effort
  if (owner !== undefined) {
    ticket.effort = owner
  }
  if (request.state === 'started' && landedAt !== undefined) {
    ticket.landedAt = landedAt
  }

  return ticket
}

function withoutLandedAt(report: TicketReport): TicketReport {
  const { landedAt: _landedAt, ...rest } = report

  return rest
}

files.hooks/tool-results.ts:
// What a finished tool call changes in the status: the task tools' results
// change the task list, the Cron tools the cron jobs, and `gh pr create` /
// `gh issue create` add links, and `gh` merges, closes and reopens change
// their state.
// A subagent's calls count as the main loop's do.

import type { ToolCallInput, ToolCallResult } from 'claude-code'

import type { SessionStatus } from '../types'
import { findCreatedLinks, findStateChanges, linkStatesChanged, linksFound } from './links'
import { formatCron } from './cron-schedule'
import { cronCreated, cronDeleted, cronListed } from './crons'
import { taskCreated, taskUpdated, todosWritten } from './tasks'

type Fields = Record<string, unknown>

/**
 * The change a finished tool call makes to the status, or null when it makes
 * none: an error, a denied call or a tool this mod does not read.
 */
export function toolResultChange(
  call: ToolCallInput,
  answer: ToolCallResult,
  at: number,
): ((status: SessionStatus) => SessionStatus) | null {
  if (answer.deny !== undefined || answer.isError === true) {
    return null
  }
  const input = call as unknown as Fields
  const result = asFields(answer.result)

  switch (call.tool) {
    case 'TaskCreate': {
      const task = asFields(result?.task)
      const id = text(task?.id)
      if (id === undefined) {
        return null
      }
      const subject = text(task?.subject) ?? text(input.subject) ?? id

      return status => taskCreated(status, { id, subject, activeForm: text(input.activeForm) }, at)
    }
    case 'TaskUpdate': {
      const id = text(result?.taskId) ?? text(input.taskId)
      if (id === undefined || result?.success === false) {
        return null
      }
      const statusChange = asFields(result?.statusChange)
      const next = taskStatus(statusChange?.to) ?? taskStatus(input.status)

      return status =>
        taskUpdated(
          status,
          { id, status: next, subject: text(input.subject), activeForm: text(input.activeForm) },
          at,
        )
    }
    case 'CronCreate': {
      const id = text(result?.id)
      const prompt = text(input.prompt)
      if (id === undefined || prompt === undefined) {
        return null
      }
      const job = {
        id,
        schedule: scheduleText(text(input.cron), text(result?.humanSchedule)),
        prompt,
        recurring: result?.recurring === true,
      }

      return status => cronCreated(status, job, at)
    }
    case 'CronDelete': {
      const id = text(result?.id) ?? text(input.id)

      return id === undefined ? null : status => cronDeleted(status, id, at)
    }
    case 'CronList': {
      if (!Array.isArray(result?.jobs)) {
        return null
      }
      const listed = result.jobs.flatMap(job => text(asFields(job)?.id) ?? [])

      return status => cronListed(status, listed, at)
    }
    case 'TodoWrite': {
      const todos = Array.isArray(result?.newTodos) ? result.newTodos : input.todos
      if (!Array.isArray(todos)) {
        return null
      }

      return status => todosWritten(status, todos.flatMap(todoItem), call.agentId, at)
    }
    case 'Bash': {
      const command = text(input.command) ?? ''
      const output = [text(result?.stdout), text(answer.result), text(answer.text)]
        .filter(part => part !== undefined)
        .join('\n')
      const found = findCreatedLinks(command, output)
      const changes = findStateChanges(command, output)
      if (found.length === 0 && changes.length === 0) {
        return null
      }

      return status => linkStatesChanged(linksFound(status, found, { agentId: call.agentId, at }), changes)
    }
    default:
      return null
  }
}

/**
 * A job's schedule as the pane shows it: the cron expression as short text;
 * else CronCreate's `humanSchedule` (live, it is the expression itself); else
 * the expression.
 */
function scheduleText(cron: string | undefined, human: string | undefined): string {
  return (cron === undefined ? undefined : formatCron(cron)) ?? human ?? cron ?? ''
}

function todoItem(value: unknown): { content: string; status: 'pending' | 'in_progress' | 'completed'; activeForm?: string }[] {
  const todo = asFields(value)
  const content = text(todo?.content)
  const status = taskStatus(todo?.status)
  if (content === undefined || status === undefined || status === 'deleted') {
    return []
  }

  return [{ content, status, activeForm: text(todo?.activeForm) }]
}

function taskStatus(value: unknown): 'pending' | 'in_progress' | 'completed' | 'deleted' | undefined {
  return value === 'pending' || value === 'in_progress' || value === 'completed' || value === 'deleted'
    ? value
    : undefined
}

function asFields(value: unknown): Fields | undefined {
  return typeof value === 'object' && value !== null ? (value as Fields) : undefined
}

function text(value: unknown): string | undefined {
  return typeof value === 'string' ? value : undefined
}

files.hooks/palette.ts:
// The colours the pane and the band draw with, by what they mean. Each is a
// key of Claude Code's theme, so it reads in light and dark themes alike, on
// the terminal and on the desktop. Headings are bold and labels dim; colour
// marks only these.

export const COLOR = {
  /** What needs the person: blocked decisions, blockers, the decisions asked before settling, a blocked band. */
  attention: 'warning',
  /** A session at work: the In progress state. The progress bars stay neutral. */
  done: 'success',
  /** What names a thing: item ids and the tickets being built. */
  accent: 'suggestion',
  /** A session wrapping up: the Settling state. */
  closing: 'planMode',
  /** An open pull request or issue in the Links section. */
  open: 'success',
  /** A merged pull request or a closed issue: the theme's purple for a merge. */
  merged: 'merged',
  /** A pull request closed without merging. */
  closedUnmerged: 'error',
} as const

files.hooks/shell.ts:
// A Bash command as the simple commands it runs, for the hooks that read a
// command's text: links.ts and effort.ts. It drops heredoc bodies, so text a
// command only feeds to a program (a script, a file) is never read as a
// command, and splits on `&&`, `||`, `;`, `|` and newlines outside quotes and
// command substitutions. It reads enough shell to tell commands apart, not to
// run them.

/** A heredoc's start: `<<EOF`, `<<-EOF`, `<<'EOF'` or `<<"EOF"`. */
const HEREDOC = /^<<(-?)[ \t]*(?:'([^']*)'|"([^"]*)"|\\?([A-Za-z0-9_.-]+))/

/** The words before a command that are not the command: keywords, groups, `!` and `NAME=value`. */
const PREFIX = /^(?:(?:do|then|else|elif|if|while|until|time)\s+|[({!]\s*|[A-Za-z_]\w*=(?:'[^']*'|"[^"]*"|[^\s'"]*)\s+)/

/** A heredoc whose body is still to skip. */
type Heredoc = { end: string; isTabbed: boolean }

/**
 * The simple commands a Bash command runs, in order, each trimmed and
 * without its leading keywords (`do`, `then`, …), groups and variable
 * assignments; heredoc bodies dropped. A separator inside quotes or a
 * `$(…)` does not split.
 */
export function simpleCommands(command: string): string[] {
  const parts: string[] = []
  let part = ''
  // The open quotes and substitutions, innermost last: `'`, `"` or `(`.
  const open: string[] = []
  let heredocs: Heredoc[] = []
  let at = 0

  const finish = () => {
    const simple = withoutPrefix(part.trim())
    if (simple !== '') {
      parts.push(simple)
    }
    part = ''
  }

  while (at < command.length) {
    const char = command[at] ?? ''
    const inner = open[open.length - 1]
    if (inner === "'") {
      part += char
      at += 1
      if (char === "'") {
        open.pop()
      }
      continue
    }
    if (char === '\\') {
      part += command.slice(at, at + 2)
      at += 2
      continue
    }
    if (inner === '"') {
      if (char === '"') {
        open.pop()
      } else if (command.startsWith('$(', at)) {
        open.push('(')
        part += '$('
        at += 2
        continue
      }
      part += char
      at += 1
      continue
    }

    // Outside quotes: at the top, or in a `$(…)`.
    const heredoc = command.startsWith('<<<', at) ? null : HEREDOC.exec(command.slice(at))
    if (heredoc !== null) {
      heredocs.push({ end: heredoc[2] ?? heredoc[3] ?? heredoc[4] ?? '', isTabbed: heredoc[1] === '-' })
      part += heredoc[0]
      at += heredoc[0].length
      continue
    }
    if (char === '\n' && heredocs.length > 0) {
      at = afterBodies(command, at + 1, heredocs)
      heredocs = []
      if (open.length === 0) {
        finish()
      } else {
        part += '\n'
      }
      continue
    }
    if (char === "'" || char === '"' || char === '(') {
      open.push(char)
    } else if (char === ')' && open.length > 0) {
      open.pop()
    } else if (open.length === 0) {
      const separator = ['&&', '||'].find(text => command.startsWith(text, at)) ?? (/[;|\n]/.test(char) ? char : null)
      if (separator !== null) {
        finish()
        at += separator.length
        continue
      }
    }
    part += char
    at += 1
  }
  finish()

  return parts
}

/** Where the command goes on after the heredoc bodies that start at `from`. */
function afterBodies(command: string, from: number, heredocs: readonly Heredoc[]): number {
  let at = from
  for (const heredoc of heredocs) {
    while (at < command.length) {
      const lineEnd = command.indexOf('\n', at)
      const end = lineEnd === -1 ? command.length : lineEnd
      const line = command.slice(at, end)
      at = lineEnd === -1 ? command.length : lineEnd + 1
      if ((heredoc.isTabbed ? line.replace(/^\t+/, '') : line) === heredoc.end) {
        break
      }
    }
  }

  return at
}

/** A simple command without the keywords, groups and assignments before it. */
function withoutPrefix(part: string): string {
  let simple = part
  for (let prefix = PREFIX.exec(simple); prefix !== null; prefix = PREFIX.exec(simple)) {
    simple = simple.slice(prefix[0].length)
  }

  return simple
}

