  const { Box, Text } = ui
  const state = status === null ? null : headline(status)
  if (state === null) {
    return null
  }
  const color = STATE_COLOR[state]

  return (
    <Box key="state" flexDirection="column">
      {color === null ? (
        <Text bold dimColor>{`● ${HEADLINE_TEXT[state]}`}</Text>
      ) : (
        <Text bold color={color}>{`● ${HEADLINE_TEXT[state]}`}</Text>
      )}
    </Box>
  )
}

